window.POETRY_REGISTER("v5-extra-12-7-0-4433a76f28fb.js",{"poems":[[15384,2],[23602,2],[51933,2],[52094,2],[52800,2],[52804,2],[53040,2],[53492,2],[53745,2],[53772,2],[54240,2],[54589,2],[54986,2],[55193,2],[56899,2],[58168,2],[58885,2],[87526,7],[92652,7],[141934,7],[160316,7],[165685,7],[178362,7],[180834,7],[187948,7],[202399,7],[209864,7],[221357,7],[221364,7],[229247,7],[251182,7],[257424,7],[260392,7],[263614,7],[265019,7],[267739,7],[268208,7],[269874,7],[272362,7],[275121,7],[281635,7],[288139,7],[293945,7],[301577,7],[301600,7],[303103,7],[306892,7],[317948,7],[331213,7],[339660,9],[358684,9],[359818,9],[360398,9],[363054,9],[368191,10],[368852,10],[369896,10],[378810,10],[420547,8],[420584,8],[425456,8],[442438,8],[451334,8],[451346,8],[466216,8],[472608,8],[473640,8],[477829,8],[502482,8],[518092,8],[518167,8],[531075,8],[534134,8],[546099,8],[546107,8],[550579,8],[557825,8],[571467,8],[589882,8],[616877,8],[625634,8],[627359,8],[631131,8],[634949,15],[635640,15],[636941,15],[647926,15],[650074,5],[653531,5],[661866,5],[661949,5],[669214,5],[670047,5],[670944,5],[681111,5],[681509,5],[682077,5],[683672,5],[695204,5],[723185,5],[724561,5]],"pairs":[["非数仞高墙不足以逞其笔势","或逢花笺与绢素",0],["无乃在乎昭昭乎曰与夫日星","何三光之竝照兮",1],["此句或迻作一斗黄金一斗粟","按下斗字应作升",2],["我颇疑猜作者所奉怀的殿下","就是信安王李祎",3],["诸道得营都统高骈开府淮南","辟公为都统巡官",4],["契家入江阳郡伽倻山以终焉","葬在湖西之鸿山",4],["渐有人重视唐诗全集的编刻","便断代分期出书",5],["仅出剡溪三字为李德裕所云","余皆蔡宽夫之语",6],["应为指盖嘉运采辑奏进之作","而非指其所自作",7],["详诗意及义净所敍前后文意","此诗应为玄逵作",8],["伪托时代仅知在明中叶以前","以下录附首二首",9],["第一首诗作者姓名官职不详","从第二首诗题看",10],["张叔良为广德二年登进士第","与此云大历相合",11],["其间冯宿冯定李绅皆唐显人","灵澈以诗名后世",12],["吕益柔刻三十九首于枫泾寺","云得其父遗编中",13],["中华书局影印本此卷为宋刻","前为李白同题诗",14],["同书全录唐人传奇之文甚众","今尚难遽作论断",15],["然此诗显为时人咏其事之作","与前列诸诗不同",16],["惟侯之灵一贫如洗与流比长","万斯年兮福吾乡",17],["赤日上煎兮胶津蹙气塞咽喉","胸荡肩挨同轭牛",18],["一日一夕兮飞相往来不可数","使其开口而言兮",19],["因什么却向剑门关上月重圆","究竟光明终一体",20],["或有画箕踞而坐者号大着肚","旧有赞颂皆鄙语",21],["那堪更言七坐道场三奉诏旨","大似郑州出曹门",22],["长鲸𩥇海兮光漾漾珊瑚之林","千里雪翻波渺渺",23],["水多深阻兮不能为吾之舟航","徒顿驾以独宿兮",24],["乃遵黄面老子二千年前话霸","验蜡人彻底冰清",25],["又不能持斗魁以回万物之春","食不足以活妻子",26],["齐楚岂不强而大兮吾王以妥","贤于国其无裨兮",27],["非我翁春日览镜大篇之舂容","翁顾笑而惊寤兮",28],["民依慈母亦复不能如汉杜诗","一官彊颜窃温饱",29],["谓彼不吾即而吾亦为此惧也","岁贸贸其婉晚兮",30],["又不能桑麻谷粟去作田舍翁","苦心竭虑淡泊音",31],["此吾故人野塘苏元龙之墨迹","中有石屏老泪痕",32],["尽日仅一逄樵叟鹤发而眉厖","路逶迤而险阻兮",33],["又不见坡仙咏安期宅边之蒲","枣失其种岂复得",34],["天都一峰杰出于三十六峰兮","星斗森罗挂珠殿",35],["门前幸有千朵青山万朵青山","徘徊赢得倚栏干",36],["不如昭文氏之琴不鼓无亏成","芭蕉潄潄连夜雨",37],["又不愿金狨系马西池万人看","只愿宽闲寂寞滨",38],["又不见去年蕨根掘尽不充口","妻孥长恐不相守",39],["胡不从湘君缓移桂櫂搴芙蕖","乃甘卑渫贾众怨",40],["死生契阔兮怅十二里之高冈","歌薤露之卒章兮",41],["只忧兄弟不会狗子无佛性话","常啼菩萨卖心肝",42],["问祈国里曲则想持帽于方童","伟哉圣贤所森布",43],["可以奉五百罗汉于东西两阿","我仗我佛大势力",44],["只有一口吹毛利剑凛凛如霜","要为人剪除毛病",45],["天下大禅佛枉自吃了四藤条","说著令人恨不消",46],["拄杖子向十字街头扬声大叫","炎炎六月火生冰",47],["雄奇秀丽胡为乎此山兮独钟","长江西来一万里",48],["往与凌云山人披虎豹谒太清","是时东风满瑶京",49],["孰为使之朝禁林而暮采石也","其天宝之嬖幸欤",50],["洞庭上立七十二朵之青瑶岑","莫邪老铁作龙吼",51],["吹以东坡吊孟德之箫声呜呜","归来锦囊压蹇驴",52],["乃是韩魏国忠献五世之曾孙","临平湖开石封发",53],["乃云太上亲传一管笔三轴经","无忧祖师传至我",54],["匡庐五老与石城北固遥相连","冰峦雪壑互起伏",55],["君不见延陵季子碑上仅十字","千载万载生光辉",56],["君不见江南人家种麻胜种田","腊月忍冻衣无边",57],["社结莲以植花林卖杏而守虎","驱飞锡兮逾险阻",58],["赋归来兮彭泽怀高士于南昌","清风至节照今古",58],["岂无忠义者肝胆涂地捐身躯","黎民流徙困征需",59],["笑彼杨朱不肯拔一毛何愚哉","上天生财自有数",60],["𪾢睆以相逐兮似亦媚此晴晖","汉之曲兮湘之南",61],["我歌北崖兮气势上与浮云齐","光景凌乱干虹蜺",62],["招潘君兮子来共千岁以一息","潘君归语衡山氏",63],["其山乃在幽州之阻辽水之涯","盘纡峍屼几千仞",64],["掷梭一女兮使人嗟叹空徜徉","使人嗟叹空徜徉",65],["达副将军遇春提兵九十六万","戈鋋甲胄如浮云",66],["岂能与蜉蝣翠羽楚楚争春秋","为君笑尽一杯酒",67],["又不能拂衣故园补缀先人草","万里迢遥魄伴魂",68],["君不见燕喜天藏地设待人成","诛茅架阁向幽境",69],["滔滔东奔吾不知其几千万里","长江大河一线来",70],["复有人中之凤览德辉而来仪","雍雍喈喈鸣舜禹",71],["胡为乎陵谷倒置变态也非常","千竿绿竹覆壶觞",72],["小伍常戒酒今夕何堪负月明","世路风波浑不定",73],["岂必太行羊肠之险能死人为","万盘历尽天渐黑",74],["飘飖夜有光袅袅花前双凤皇","色如冰雪声如簧",75],["回风萧萧兮燕云万里望空劳","客子悲来病骨高",76],["但愿千万年薄海内外无远迩","遗民在在安田里",77],["去者如长江之水滚滚而不回","人生百年复何有",78],["飘飖夜有光袅袅花前双凤皇","色如冰雪声如簧",79],["达副将军遇春提兵九十六万","戈鋋甲胄如浮云",80],["又不能拂衣故园补缀先人草","万里迢遥魄伴魂",81],["何日将予兮直上千峰与万峰","有姊有姊夫早撇",82],["吾不能如鹿豕之蠢木石之顽","安能与人无往还",83],["小坐香肩比乍听晓莺啼梦里","海棠又湿鹦哥嘴",84],["会当直入四百峰师事安期生","向人贷粟不得饱",85],["忙问花翁在否如今酣饮非旧","吴酸越辣多滋味",86],["他可才稳坐在龙床不用动身","灵长自古数周朝",87],["你看他照样的披挂不差一丝","年年五丈起秋风",87],["此独晦匿于震泽之滨缥缈峰","大材僻处自矜贵",88],["狂呼潋滟于山僧送客忘言说","水自飞流石自横",89],["就坐待蓬莱清浅始悔朱颜衰","风尘回首驱征铎",90],["我昔从师游之无不识童蒙求","先生口授兼指画",91],["又不知是山还是积雪之冻凝","便思移入广寒殿",92],["驻舆意不乐海山仙人排云落","鞭石驱海戴六鳌",93],["乃使五洋沉军舰六洲平战垒","于是天地乃清宁",94],["劳君打包出东林骑鹤离武昌","与君携手南极旁",95],["其人悲歌慷慨能谈兵而使酒","何意乃有高足生",96],["胡为乎职司喉舌而箕张其口","圣人御极不鸣条",97],["炎歊来往于烟雨寂寞之空蒙","上雾下湿天日暗",98],["溪谷岚气瘴毒侵鸡肋之微躬","斫竹为床聊偃仰",98],["君不见古来穷达变化犹飘云","南山尚有射虎手",99],["而一抔土左右毗连犹吝滴涓","导扬和气赖鸿笔",100]]});
